import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db, setCurrentRlsServiceRole } from '@/lib/db'
import { adminPlanOverrideSchema, type AdminPlanOverride } from '@/lib/admin/planOverride'
import { logAuditEvent } from '@/lib/enterprise/auditTrail'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface UserRow {
  id: string
}

interface ExistingSubscriptionRow {
  plan_id: string | null
  status: string | null
}

export const dynamic = 'force-dynamic'

/**
 * PATCH /api/admin/users/override-plan
 *
 * Override a user's subscription plan (platform admin only).
 *
 * Body:
 *   email  (string, required) — user email to look up
 *   plan   (a current subscription catalogue plan ID, required)
 *   days   (integer from 1 to 3650, optional, default 30) — duration in days
 */
export const PATCH = apiHandler(
  { auth: true, roles: ['admin', 'super_admin'], schema: adminPlanOverrideSchema, rateLimit: { max: 60, windowMs: 60000 } },
  async (request, ctx) => {
    setCurrentRlsServiceRole('platform_admin')
    const { email, plan, days } = ctx.body as AdminPlanOverride
    const expiresAt = new Date(Date.now() + days * 86400000).toISOString()
    const clientIp = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
    const userAgent = request.headers.get('user-agent') || undefined

    const override = await db.transaction(async client => {
      const userRes = await client.query<UserRow>(
        'SELECT id FROM users WHERE email = $1 LIMIT 1 FOR UPDATE',
        [email],
      )
      const userId = userRes.rows[0]?.id
      if (!userId) return null

      const previousRes = await client.query<ExistingSubscriptionRow>(
        'SELECT plan_id, status FROM user_subscriptions WHERE user_id = $1 LIMIT 1 FOR UPDATE',
        [userId],
      )
      const previous = previousRes.rows[0]

      await client.query(
        `INSERT INTO user_subscriptions (user_id, plan_id, status, current_period_start, current_period_end)
         VALUES ($1, $2, 'active', NOW(), $3)
         ON CONFLICT (user_id)
         DO UPDATE SET plan_id = $2, status = 'active', current_period_start = NOW(), current_period_end = $3`,
        [userId, plan, expiresAt],
      )

      await logAuditEvent({
        userId: ctx.userId,
        action: 'subscription.plan.override',
        resourceType: 'user_subscriptions',
        resourceId: userId,
        details: {
          targetEmail: email,
          previousPlan: previous?.plan_id ?? null,
          previousStatus: previous?.status ?? null,
          newPlan: plan,
          durationDays: days,
        },
        ipAddress: clientIp,
        userAgent,
        timestamp: new Date(),
      }, client)

      return { userId, previousPlan: previous?.plan_id ?? null }
    })

    if (!override) return apiSuccess({ error: 'User not found' }, 404)

    return apiSuccess({
      userId: override.userId,
      email,
      plan,
      expiresAt,
      days,
      previousPlan: override.previousPlan,
    })
  },
)
